//! Upstream parity fixture: `tests/fixtures/metadata_golden.json`,
//! generated by `scripts/gen_metadata_golden.ts` running each case
//! through upstream `extractDocumentMetadata`
//! (`src/metadata.ts`, npm `yaml` 2.9 core schema).
//!
//! For every case, `metadata::extract_document_metadata` must produce a
//! `metadata_json` byte-identical to upstream `JSON.stringify` (which
//! pins JS key order and number format) and an error that is `None`,
//! shares the `invalid frontmatter YAML: ` prefix when upstream's own
//! YAML error text differs (granit phrases syntax errors differently),
//! or is exactly equal.

#![allow(
    unused_crate_dependencies,
    reason = "each test binary only uses a subset of the package deps"
)]
#![allow(
    clippy::tests_outside_test_module,
    clippy::unwrap_used,
    clippy::missing_assert_message,
    clippy::panic,
    clippy::indexing_slicing,
    reason = "idiomatic test-code patterns"
)]

use std::fs;
use std::path::Path;

use qmd::{METADATA_EXTRACTION_VERSION, extract_document_metadata};
use serde_json::Value;

const YAML_PREFIX: &str = "invalid frontmatter YAML: ";

/// Registered deviations (qmd-study parity-matrix §12, deviations 48 and
/// 49): `(case, our metadata_json, our error)`. Our output is pinned
/// exactly, and the test also asserts upstream still differs, so a
/// regenerated fixture that converges fails loudly.
const DEVIATIONS: &[(&str, &str, Option<&str>)] = &[
    // granit-parser accepts under-indented flow collections (PyYAML
    // compatibility); npm yaml rejects them (deviation 48).
    ("flow seq under-indented", r#"{"tags":["a","b"]}"#, None),
    (
        "flow map under-indented",
        "{}",
        Some(
            "metadata key \"m\": unsupported value type — use strings, numbers, booleans, or flat arrays of one of those",
        ),
    ),
    // Rust strings cannot hold a lone UTF-16 surrogate; granit rejects
    // the escape where JS keeps it (deviation 49).
    (
        "lone surrogate escape",
        "{}",
        Some(
            "invalid frontmatter YAML: while parsing a quoted scalar, found high surrogate without following low surrogate",
        ),
    ),
];

#[test]
fn metadata_golden_matches_upstream() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let fixture: Value = serde_json::from_str(
        &fs::read_to_string(root.join("tests/fixtures/metadata_golden.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        fixture["extraction_version"].as_i64().unwrap(),
        METADATA_EXTRACTION_VERSION,
        "fixture generated against a different extraction version — regenerate with \
         scripts/gen_metadata_golden.ts"
    );

    let cases = fixture["cases"].as_array().unwrap();
    let mut failures: Vec<String> = Vec::new();
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let path = case["path"].as_str().unwrap();
        let content = case["content"].as_str().unwrap();
        let want_json = case["metadata_json"].as_str().unwrap();
        let want_error = &case["error"];

        let got = extract_document_metadata(content, path);
        if let Some((_, our_json, our_error)) = DEVIATIONS.iter().find(|(n, _, _)| *n == name) {
            if got.metadata.to_json() != *our_json || got.error.as_deref() != *our_error {
                failures.push(format!(
                    "{name}: registered deviation changed — got {} / {:?}",
                    got.metadata.to_json(),
                    got.error
                ));
            }
            if want_json == *our_json && want_error.as_str() == *our_error {
                failures.push(format!(
                    "{name}: upstream now matches us — drop the deviation"
                ));
            }
            continue;
        }
        if got.extraction_version != METADATA_EXTRACTION_VERSION {
            failures.push(format!(
                "{name}: extraction_version {} != {METADATA_EXTRACTION_VERSION}",
                got.extraction_version
            ));
        }
        if got.metadata.to_json() != want_json {
            failures.push(format!(
                "{name}: metadata_json got {} want {want_json}",
                got.metadata.to_json()
            ));
        }
        match (want_error.as_str(), got.error.as_deref()) {
            (None, Some(got_err)) => {
                failures.push(format!("{name}: got error {got_err:?}, want none"));
            }
            (Some(want_err), None) => {
                failures.push(format!("{name}: got no error, want {want_err:?}"));
            }
            // YAML parser errors need only share the prefix — granit
            // and npm yaml phrase them differently.
            (Some(want_err), Some(got_err))
                if want_err.starts_with(YAML_PREFIX) && !got_err.starts_with(YAML_PREFIX) =>
            {
                failures.push(format!(
                    "{name}: got error {got_err:?}, want prefix {YAML_PREFIX:?} \
                     (upstream {want_err:?})"
                ));
            }
            (Some(want_err), Some(got_err))
                if !want_err.starts_with(YAML_PREFIX) && got_err != want_err =>
            {
                failures.push(format!("{name}: got error {got_err:?}, want {want_err:?}"));
            }
            (None, None) | (Some(_), Some(_)) => {}
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} golden cases failed:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}
